"""Regression for readiness budget versus actual transaction budget; no live mounts or network changes."""
import pathlib
import subprocess
import tempfile
source = pathlib.Path(__file__).resolve().parents[1] / "module/bin/fcm_dns_hosts_fallback.sh"
script = "#!/bin/sh\nset -e\nT=$2\n. \"$1\"\nfcm_hosts_tools_ready(){ return 0; }\nRUNDIR=\"$T/state-test\"\nmkdir -p \"$RUNDIR\"\nDOWN_FILE=\"$RUNDIR/down\"\nATTEMPT_FILE=\"$RUNDIR/attempt\"\nPATHLOG_FILE=\"$RUNDIR/path\"\nDNSLOG_FILE=\"$RUNDIR/dnslog\"\nDNSFAIL_FILE=\"$RUNDIR/dnsfail\"\nDNSOK_FILE=\"$RUNDIR/dnsok\"\nSOFT_RECONNECT_FILE=\"$RUNDIR/soft\"\nMODDIR=\"$T\"\nIPTABLES_WAIT_SECONDS=5\nLOG=\"$RUNDIR/test.log\"\nlog_msg(){ printf '%s\\n' \"$*\" >> \"$LOG\"; }\nfcm_hosts_wake_acquire(){ log_msg ACQUIRE; }\nfcm_hosts_wake_release(){ log_msg RELEASE; }\ndns_active_default_netid(){ echo 100; }\ngms_uid_for_probe(){ echo 10139; }\nfcm_state(){ echo disconnected; }\nandroid_resolve_mtalk(){ return 1; }\nfcm_hosts_netd_pid(){ echo 123; }\nfcm_hosts_recover_abandoned(){ return 0; }\nfcm_hosts_connection_verified(){ return 1; }\niptables(){ return 1; }\nrun_timeout(){\n case \"$2\" in\n connectivity) printf 'Active default network: 100\\n NetworkAgentInfo{network{100} ni{MOBILE CONNECTED} nc{[ Transports: CELLULAR Capabilities: INTERNET&NOT_VPN ]}}\\n';;\n dnsresolver) printf 'NetId: 100\\n  DNS servers:\\n    223.87.253.100 (3, 3)\\n  Private DNS mode: OFF\\n  TransportType: CELLULAR\\n';;\n esac\n}\nmock_bb(){ log_msg \"MOCK_TRANSACTION $*\"; return 7; }\nBB=mock_bb\n: > \"$LOG\"\nprintf '1000\\n' > \"$DOWN_FILE\"\nfcm_hosts_candidate(){ return 1; }\nfor n in 2000 2900 3800; do\n if fcm_hosts_fallback \"$n\" 1000 1000 1999; then exit 11; fi\n test ! -e \"$RUNDIR/fcm_dns_hosts_transaction.state\"\ndone\n[ \"$(grep -c 'stage=no-tls-verified-candidate' \"$LOG\")\" = 3 ]\n[ \"$(grep -c RELEASE \"$LOG\")\" = 3 ]\n# A fourth readiness success must dispatch even after three failures.\nfcm_hosts_candidate(){ echo 142.250.99.188; }\nif fcm_hosts_fallback 4700 1000 3700 4699; then exit 12; fi\ntest -f \"$RUNDIR/fcm_dns_hosts_transaction.state\"\nread stamp ts attempts < \"$RUNDIR/fcm_dns_hosts_transaction.state\"\n[ \"$stamp\" = 1000 ] && [ \"$attempts\" = 1 ]\n[ \"$(grep -c MOCK_TRANSACTION \"$LOG\")\" = 1 ]\n[ \"$(grep -c RELEASE \"$LOG\")\" = 4 ]\n# Same outage with stale network: never dispatch.\nprintf '4700\\n' > \"$RUNDIR/fcm_dns_hosts_prepare.state\"\nprintf '1000 4700 1\\n' > \"$RUNDIR/fcm_dns_hosts_transaction.state\"\nfcm_state(){ echo connected; }\nif fcm_hosts_fallback 5600 1000 4600 5599; then exit 13; fi\n[ \"$(grep -c MOCK_TRANSACTION \"$LOG\")\" = 1 ]\ngrep -q 'stage=mcs-no-longer-disconnected' \"$LOG\"\necho PASS_FULL_STATE_MACHINE\ncat \"$LOG\"\n"
with tempfile.TemporaryDirectory() as tmp:
    result = subprocess.run(["sh", "-c", script, "test", str(source), tmp], text=True, capture_output=True)
    assert result.returncode == 0, result.stdout + result.stderr
    assert "PASS_FULL_STATE_MACHINE" in result.stdout
    print(result.stdout)
